import XCTest
@testable import VocabFlow

/// Cross-checks the engine against the backend's own `Board` and `replay` (vocab-backend
/// `src/modules/challenge/domain/match-madness.ts`). The fixture was generated by running that code on a level 3 plan
/// (16 occurrences of 12 meanings, so 4 repeats) with one wrong attempt; the backend accepted the events (3 stars).
/// Regenerate it whenever the backend's board rules change.
final class MatchMadnessBackendParityTests: XCTestCase {
    private struct Fixture: Decodable {
        struct Step: Decodable {
            let words: [String]
            let meanings: [String]
        }

        let plan: ChallengeRunPlan
        let steps: [Step]
        let events: [MatchAttemptEvent]
    }

    func testEngineReproducesTheBackendBoardAndEvents() throws {
        let fixture = try JSONDecoder().decode(Fixture.self, from: Data(Self.json.utf8))
        let engine = MatchMadnessEngine(plan: fixture.plan)
        var state = engine.initialState()
        var step = 0
        XCTAssertEqual(state.wordOrder, fixture.steps[0].words)
        XCTAssertEqual(state.meaningOrder, fixture.steps[0].meanings)

        for event in fixture.events {
            state = engine.reduce(state, .tapWord(tileID: event.wordTileId, elapsedMs: event.elapsedMs)).state
            let result = engine.reduce(state, .tapMeaning(tileID: event.meaningTileId, elapsedMs: event.elapsedMs))
            state = result.state
            switch result.feedback {
            case .correct:
                step += 1
                XCTAssertEqual(state.wordOrder, fixture.steps[step].words, "word column after \(step) matches")
                XCTAssertEqual(state.meaningOrder, fixture.steps[step].meanings, "meaning column after \(step) matches")
            case .goalReached:
                step += 1
            case .wrong:
                XCTAssertEqual(state.wordOrder, fixture.steps[step].words, "a wrong pair doesn't reorder")
            case .none, .selected, .deselected:
                XCTFail("event \(event.seq) used a tile that wasn't on the board")
            }
        }

        XCTAssertEqual(step, fixture.steps.count)
        XCTAssertEqual(state.phase, .goalReached)
        XCTAssertEqual(state.events, fixture.events)
        XCTAssertEqual(state.wrongCount, 1)
        XCTAssertEqual(state.longestCombo, 11)
        XCTAssertEqual(state.provisionalScore, 2520, "the server's score, clear bonus included")
        let body = MatchMadnessEngine.commitBody(state, reason: .goalReached, endedElapsedMs: 99_999)
        XCTAssertEqual(body.endedElapsedMs, 21_500, "goal_reached ends exactly at the last event")
    }

